        assert_eq!(solve(vec![0, 0, 0, 0, 0]), -1);
        // sum = 1+1+1+1+2 = 6 => not divisible by 5
        assert_eq!(solve(vec![1, 1, 1, 1, 2]), -1);
        // sum = 100+100+100+100+100 = 500 => 500/5 = 100
        assert_eq!(solve(vec![100, 100, 100, 100, 100]), 100);
